import base64
import requests
import json
import os
class EsUtil:
    def __init__(self,ip,es_user_name=None,es_pass_word=None,port=9200):
        self.ip=ip
        self.port=port
        self.user_name =  os.environ.get("es_user_name",es_user_name)
        self.pass_word = os.environ.get("es_pass_word",es_pass_word)
        self.authorization = base64.b64encode(
            f'{self.user_name}:{self.pass_word}'.encode()).decode()
        self.source_url = f'https://{self.ip}:{self.port}'

    def log(self,*args):
        print("LOG:",*args)
    

    
    def insert_key_value(self, index, tp, key, value):
        return self.put(f'{index}/{tp}/{key}', value)

    def create_index(self, key):
        return self.put(key)

    def remove_index(self, key):
        return self.delete(key)
    
    def delete(self, key,**kw):
        return self.http("delete",key,**kw)

    def put(self, key, value=None,**kw):
        return self.http("put",key,data=value,**kw)
    def post(self, uri, value=None,**kw):
        return self.http("post",uri,data=value,**kw)
    def get(self, key,**kw):
        return self.http("get",key,**kw)

    def http(self,method,uri,data=None,timeout=360,log=False,**kw):
        params=dict()
        if method == 'get':
            params["data"]=data
        else:
            params["json"]=data
        url=f'{self.source_url}{uri}'
        res = requests.request(
            method,
            url,
            timeout=timeout,
            headers={
                'Authorization': f"Basic {self.authorization}"
            },
            verify=False,
            **params
        )
        if log:
            self.log(f'{method} {url} {data} {res.status_code} {res.text}')
        return res.text
    
    def get_index_value(self, key):
        return json.loads(self.get(f'/{key}/_search'))

    def get_index_by_key(self, key):
        datas = self.get(f"/_cat/indices/{key}*")
        ret = []
        for line in datas.split("\n"):
            lines = [v for v in line.split(" ") if v]
            if len(lines) >= 2:
                key = lines[2]
                ret.append(key)
        if len(ret) == 0:
            self.log("get_nulldata", datas)
        return ret
    
    def reindex(self, index,reindex):
        self.post(
            "/_reindex?wait_for_completion=true&refresh=true",
            {
                "source":{"index":index},"dest":{"index":reindex}
            },
            log=True
        )
        self.post(f"/{index}/_count",log=True)
        self.post(f"/{reindex}/_count",log=True)
        self.delete(f"/{index}",log=True)

    def reindex_two(self,src,dst=None):
        if dst is None:
            dst=src+"_reindex"
        self.reindex(src,dst)
        self.reindex(dst,src)